          "headingGap": "space.4",
          "maxDepth": "2"
        }
      }
    }
  ],
  "states": ["default", "narrow"],
  "components": [
    "component.card",
    "component.surface",
    "component.toolbar"
  ],
  "rules": [
    "layout.grouping",
    "color.semantic",
    "a11y.control-name"
  ]
