      {
        type: "object",
        properties: {
          variants: {
            type: "object",
            additionalProperties: {
              type: "object",
              properties: { name: { type: "string" }, variants: { type: "array", items: { type: "string" } } },
              required: ["name", "variants"],
            },
          },
        },
        additionalProperties: false,
      },
