import { getAttribute, getAttributeValue, getTagName } from "../jsx.mjs";

const nativeTags = new Set(["button", "table", "select", "input"]);

export default {
  meta: {
    type: "problem",
    docs: { description: "契約に存在しない UI 部品(独自 HTML、契約外の HeroUI import、Issue 対象外の文言)を検出する" },
    schema: [
      {
        type: "object",
        properties: {
          approvedImports: { type: "array", items: { type: "string" } },
          forbiddenText: { type: "array", items: { type: "string" } },
        },
        additionalProperties: false,
      },
    ],
    messages: {
      native: "{{name}}: 独自 HTML 部品ではなく HeroUI の契約コンポーネントを使ってください",
      unapprovedImport: "契約にないHeroUI import: {{name}}",
      forbiddenText: "Issue対象外のUI（削除対象: {{text}}）",
    },
  },
  create(context) {
    const options = context.options[0] ?? {};
    const approvedImports = new Set(options.approvedImports ?? []);
    const forbiddenText = options.forbiddenText ?? [];
    const sourceCode = context.sourceCode;
    return {
      Program(node) {
        if (forbiddenText.length === 0) return;
        const pattern = new RegExp(forbiddenText.map((text) => text.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")).join("|"), "g");
        for (const match of sourceCode.text.matchAll(pattern)) {
          context.report({
            node,
            loc: { start: sourceCode.getLocFromIndex(match.index), end: sourceCode.getLocFromIndex(match.index + match[0].length) },
            messageId: "forbiddenText",
            data: { text: match[0] },
          });
        }
      },
      JSXOpeningElement(node) {
        const tagName = getTagName(node.name);
        if (nativeTags.has(tagName)) {
          context.report({ node, messageId: "native", data: { name: tagName } });
        }
        const role = getAttribute(node, "role");
        if (role && getAttributeValue(role) === "dialog") {
          context.report({ node: role, messageId: "native", data: { name: "custom dialog" } });
        }
      },
      ImportDeclaration(node) {
        if (node.source.value !== "@heroui/react" || node.importKind === "type") return;
        for (const specifier of node.specifiers) {
          if (specifier.type !== "ImportSpecifier" || specifier.importKind === "type") continue;
          const imported = specifier.imported.type === "Identifier" ? specifier.imported.name : specifier.imported.value;
          if (!approvedImports.has(imported)) {
            context.report({ node: specifier, messageId: "unapprovedImport", data: { name: imported } });
          }
        }
      },
    };
  },
};
import { getBaseName } from "../jsx.mjs";

export default {
  meta: {
    type: "problem",
    docs: { description: "Example の componentUsage が求める部品が JSX に現れることを求める(import だけでは足りない)" },
    schema: [
      {
        type: "object",
        properties: {
          componentUsage: {
            type: "array",
            items: { type: "object", properties: { name: { type: "string" }, implementation: { type: "string" } }, required: ["name", "implementation"] },
          },
        },
        additionalProperties: false,
      },
    ],
    messages: { missing: "{{name}}: componentUsageで求められていますが実装に現れません" },
  },
  create(context) {
    const required = context.options[0]?.componentUsage ?? [];
    const rendered = new Set();
    return {
      JSXOpeningElement(node) {
        const base = getBaseName(node.name);
        if (base) rendered.add(base);
      },
      "Program:exit"(node) {
        for (const entry of required) {
          if (!rendered.has(entry.implementation)) context.report({ node, messageId: "missing", data: { name: entry.name } });
        }
      },
    };
  },
};
import { getAttribute, getAttributeValue, getTagName } from "../jsx.mjs";

export default {
  meta: {
    type: "problem",
    docs: { description: "HeroUI の variant を Atlas のコンポーネント契約と一致させる" },
    schema: [
      {
        type: "object",
        properties: {
          variants: {
            type: "object",
            additionalProperties: {
              type: "object",
              properties: { name: { type: "string" }, variants: { type: "array", items: { type: "string" } } },
              required: ["name", "variants"],
            },
          },
        },
        additionalProperties: false,
      },
    ],
    messages: {
      invalid: "{{name}}: {{value}}",
      dynamic: "動的なvariantのため機械判定不能: {{name}} {{text}}",
    },
  },
  create(context) {
    const variants = context.options[0]?.variants ?? {};
    return {
      JSXOpeningElement(node) {
        const component = variants[getTagName(node.name)];
        if (!component) return;
        const attribute = getAttribute(node, "variant");
        if (!attribute) return;
        const value = getAttributeValue(attribute);
        if (typeof value === "string") {
          if (!component.variants.includes(value)) {
            context.report({ node: attribute, messageId: "invalid", data: { name: component.name, value } });
          }
          return;
        }
        context.report({
          node: attribute,
          messageId: "dynamic",
          data: { name: component.name, text: context.sourceCode.getText(attribute) },
        });
      },
    };
  },
};
import { getAttribute, getAttributeValue, getTagName } from "../jsx.mjs";

export default {
  meta: {
    type: "problem",
    docs: { description: "一覧の Table は契約で定義した variant を使う" },
    schema: [{ type: "object", properties: { variant: { type: "string" } }, additionalProperties: false }],
    messages: {
      mismatch: "検出variant: {{value}}(契約は {{expected}})",
      missing: "Table.Rootを確認できません",
    },
  },
  create(context) {
    const expected = context.options[0]?.variant ?? "primary";
    let roots = 0;
    return {
      JSXOpeningElement(node) {
        const tagName = getTagName(node.name);
        if (tagName !== "Table.Root" && tagName !== "Table") return;
        roots += 1;
        const value = getAttributeValue(getAttribute(node, "variant")) ?? "primary";
        if (value === expected) return;
        context.report({ node, messageId: "mismatch", data: { value: typeof value === "string" ? value : "動的指定", expected } });
      },
      "Program:exit"(node) {
        if (roots === 0) context.report({ node, messageId: "missing" });
      },
    };
  },
};

