import { containsTag, getTagName } from "../jsx.mjs";

export default {
  meta: {
    type: "problem",
    docs: { description: "取り消せない操作は AlertDialog.Trigger(内側は HeroUI Button)から確認画面を開く" },
    // 取り消せない操作の呼び名は題材ごとに変わる（削除、無効化）。example の
    // lint.irreversibleActionPattern から渡し、その語が無い画面には確認を求めない
    schema: [
      {
        type: "object",
        properties: { pattern: { type: "string", minLength: 1 } },
        required: ["pattern"],
        additionalProperties: false,
      },
    ],
    messages: {
      noTrigger: "取り消せない操作にHeroUI AlertDialog.Triggerがありません",
      noButton: "AlertDialog.Triggerの内側にHeroUI Buttonがありません",
    },
  },
  create(context) {
    const irreversibleAction = new RegExp(context.options[0].pattern, "i");
    let hasRoot = false;
    const triggers = [];
    return {
      JSXOpeningElement(node) {
        const tagName = getTagName(node.name);
        if (tagName === "AlertDialog.Root" || tagName === "AlertDialog") hasRoot = true;
      },
      JSXElement(node) {
        if (getTagName(node.openingElement.name) === "AlertDialog.Trigger") triggers.push(node);
      },
      "Program:exit"(node) {
        if (!irreversibleAction.test(context.sourceCode.text)) return;
        if (!hasRoot || triggers.length === 0) {
          context.report({ node, messageId: "noTrigger" });
          return;
        }
        if (!triggers.some((trigger) => containsTag(trigger, "Button"))) {
          context.report({ node: triggers[0].openingElement, messageId: "noButton" });
        }
      },
    };
  },
};
import { containsTag, getAttribute, getTagName, hasOnlyWhitespaceText } from "../jsx.mjs";

export default {
  meta: {
    type: "problem",
    docs: { description: "Drawer.Root 内で Trigger と Backdrop を組にし、Trigger 自体へ主要 Button の視覚スタイルを付ける" },
    schema: [],
    messages: {
      noDrawer: "Drawer.Rootを確認できません",
      noBackdrop: "Drawer.Backdropを確認できません",
      nestedButton:
        "Drawer.Trigger内にHeroUI Buttonが入れ子です（buttonの入れ子はHTML違反）。Buttonを削除し、Drawer.Trigger自体へ主要Buttonの視覚スタイルのclassNameを付けてラベルテキストを直接入れてください",
      triggerClassName: "Drawer.Trigger自体にclassName（主要Buttonの視覚スタイル）を確認できません。ラベルはTriggerに直接入れます",
      closeTrigger: "Drawer.CloseTriggerがないか、狭い標準枠へ表示テキストを入れています",
    },
  },
  create(context) {
    let hasDrawer = false;
    let hasBackdrop = false;
    let triggerWithClassName = false;
    const nestedButtonTriggers = [];
    const closeTriggers = [];
    return {
      JSXOpeningElement(node) {
        const tagName = getTagName(node.name);
        if (tagName === "Drawer" || tagName === "Drawer.Root") hasDrawer = true;
        if (tagName === "Drawer.Backdrop") hasBackdrop = true;
        if (tagName === "Drawer.Trigger" && getAttribute(node, "className")) triggerWithClassName = true;
      },
      JSXElement(node) {
        const tagName = getTagName(node.openingElement.name);
        if (tagName === "Drawer.Trigger" && containsTag(node, "Button")) nestedButtonTriggers.push(node);
        if (tagName === "Drawer.CloseTrigger") closeTriggers.push(node);
      },
      "Program:exit"(node) {
        if (!hasDrawer) context.report({ node, messageId: "noDrawer" });
        for (const trigger of nestedButtonTriggers) context.report({ node: trigger.openingElement, messageId: "nestedButton" });
        if (!triggerWithClassName) context.report({ node, messageId: "triggerClassName" });
        if (!hasBackdrop) context.report({ node, messageId: "noBackdrop" });
        const iconOnlyClose = closeTriggers.length > 0 && closeTriggers.every(hasOnlyWhitespaceText);
        if (!iconOnlyClose) {
          context.report({ node: closeTriggers.find((element) => !hasOnlyWhitespaceText(element))?.openingElement ?? node, messageId: "closeTrigger" });
        }
      },
    };
  },
};
const colorFunctions = new Set(["rgb", "rgba", "hsl", "hsla"]);

export default {
  meta: {
    type: "problem",
    docs: { description: "CSS に色コードや rgb()/hsl() を直接書かず、semantic token の CSS 変数を使う" },
    schema: [],
    messages: { rawColor: "raw color: {{value}}。design/tokens.json に対応する CSS 変数を使ってください" },
  },
  create(context) {
    return {
      Hash(node) {
        context.report({ node, messageId: "rawColor", data: { value: `#${node.value}` } });
      },
      Function(node) {
        if (colorFunctions.has(node.name.toLowerCase())) {
          context.report({ node, messageId: "rawColor", data: { value: `${node.name}()` } });
        }
      },
    };
  },
};
export default {
  meta: {
    type: "problem",
    docs: { description: "styles.css から Atlas の HeroUI theme adapter(design/component-theme.css)を読み込む" },
    schema: [{ type: "object", properties: { path: { type: "string" } }, additionalProperties: false }],
    messages: { missing: "{{path}}の読み込みを確認できません。@import で読み込んでください" },
  },
  create(context) {
    const path = context.options[0]?.path ?? "design/component-theme.css";
    let found = false;
    return {
      Atrule(node) {
        if (node.name.toLowerCase() !== "import" || !node.prelude) return;
        if (context.sourceCode.getText(node.prelude).includes(path)) found = true;
      },
      "StyleSheet:exit"(node) {
        if (!found) context.report({ node, messageId: "missing", data: { path } });
      },
    };
